import { EventBridgeClient, PutEventsCommand } from '@aws-sdk/client-eventbridge';

const eb = new EventBridgeClient({});

await eb.send(new PutEventsCommand({
  Entries: [{
    Source: 'orders.api',
    DetailType: 'OrderPlaced',
    Detail: JSON.stringify({ orderId, customerId, total }),
    EventBusName: 'company-orders',
  }],
}));

function parseSqsBody(body: string, rawDelivery: boolean): unknown {
  if (rawDelivery) return JSON.parse(body);
  const envelope = JSON.parse(body) as { Message: string };
  return JSON.parse(envelope.Message);
}
